package models

import (
	"database/sql/driver"
	"encoding/json"
	"fmt"
	"time"
)

// sentence is a read-only copy of the sentence <-> gloss order dataset kept in the
// PJMatch/Dataset repository (Sentences/prepared_sentences_m.xlsx). Rows are created and
// updated only by database.SeedSentences; never edit them directly.
type Sentence struct {
	// ID is the sentence index from the dataset - not generated by the database
	ID           uint       `gorm:"primaryKey;autoIncrement:false" json:"id"`
	Text         string     `gorm:"type:text;not null" json:"text"`
	Glosses      StringList `gorm:"type:jsonb;not null" json:"glosses"`
	GlossesLemma StringList `gorm:"type:jsonb;not null" json:"glosses_lemma"`
	Active       bool       `gorm:"not null;default:true;index" json:"-"`
	CreatedAt    time.Time  `json:"-"`
	UpdatedAt    time.Time  `json:"-"`
}

// StringList is an ordered list of strings stored as a JSONB array
type StringList []string

func (l StringList) Value() (driver.Value, error) {
	if l == nil {
		l = StringList{}
	}
	b, err := json.Marshal([]string(l))
	if err != nil {
		return nil, err
	}
	return string(b), nil
}

func (l *StringList) Scan(src any) error {
	var data []byte
	switch v := src.(type) {
	case nil:
		*l = nil
		return nil
	case []byte:
		data = v
	case string:
		data = []byte(v)
	default:
		return fmt.Errorf("StringList: unsupported type %T", src)
	}
	return json.Unmarshal(data, (*[]string)(l))
}
